229	  // The agent the notice names: the title's for a runner run; off the thread for an
230	  // entry run — the person's command, or the marker the machinery posted — and
231	  // `atomaton` when the thread names nobody, whose command is the one path that
232	  // always resumes a node.
233	  const agent = titledAgent ?? (mostRecentAgentOn(repo, number) || "atomaton");
234	
235	  // The ending the run owed. Posted before the label work, because the comment —
236	  // not the label — is what the guard reads: this is the step that unjams the
237	  // thread, and the label is only the cache beside it.
238	  const body = missingEndingNotice(agent, values["run-url"] ?? "");
239	  const posted = gh("issue", "comment", String(number), "--repo", repo, "--body", body);
240	  if (posted.code !== 0) {
241	    console.error(`::error::reconcile_run_ending: could not post the notice on #${number}: ${posted.stderr || posted.stdout}`);
242	    process.exitCode = 1;
243	    return;
244	  }
