248	  // the ball — `thread` predates the notice above, so the notice's own ending
249	  // cannot answer here. Best-effort: a warning, never a failed step, because the
250	  // thread is healed and the label is a cache of an answer the thread now gives.
251	  const label = getLabel("in_progress");
252	  if (!hasLabel(repo, number, label)) return;
253	  if (!releasesLabel(lastEndingComment(thread.dated, endingWalkReaders), endingWalkReaders)) {
254	    console.error(`reconcile_run_ending: '${label}' stays on #${number}; the thread's last ending keeps the turn with an agent`);
